#!/usr/bin/env bash
# Generated by scripts/crosscode/picongpu.jl. Runs inside the PIConGPU container with the run
# directory at /run-dir (PM_RUN_DIR), the worktree read-only at /worktree and the GPU bound in.
# Seeds that finished in an earlier job are skipped; no new seed starts after 5400 s of this job.
set -euo pipefail
top="${PM_RUN_DIR:-/run-dir}"
cd "$top"
job_start=$(date +%s)
budget=5400
pending=""
for entry in seed-20261031:20261031 seed-20262031:20262031 seed-20263031:20263031 seed-20264031:20264031 seed-20265031:20265031 seed-20266031:20266031 seed-20267031:20267031 seed-20268031:20268031 seed-20269031:20269031 seed-20270031:20270031 seed-20271031:20271031 seed-20272031:20272031 seed-20273031:20273031 seed-20274031:20274031 seed-20275031:20275031 seed-20276031:20276031 seed-20277031:20277031 seed-20278031:20278031 seed-20279031:20279031 seed-20280031:20280031 seed-20281031:20281031 seed-20282031:20282031 seed-20283031:20283031 seed-20284031:20284031 seed-20285031:20285031 seed-20286031:20286031 seed-20287031:20287031 seed-20288031:20288031 seed-20289031:20289031 seed-20290031:20290031 seed-20291031:20291031 seed-20292031:20292031; do
  d=${entry%%:*}; seed=${entry##*:}
  grep -qF "# run $d seed $seed end:" container.txt 2>/dev/null || pending="$pending $entry"
done
[ -n "$pending" ] || { echo "# all seeds done"; exit 0; }
pm-versions > versions.toml
{
  echo "# picongpu: $PICONGPU_TAG $PICONGPU_COMMIT, backend $PIC_BACKEND"
  echo "# gpu: $(nvidia-smi --query-gpu=name,driver_version --format=csv,noheader 2>/dev/null || echo unknown)"
  echo "# cpus: $(nproc)"
  echo "# cpu model: $(grep -m1 'model name' /proc/cpuinfo | cut -d: -f2- | sed 's/^ *//')"
  echo "# compile start: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)"
} >> container.txt
rm -rf setup
pic-create "$PIC_EXAMPLES/Empty" setup > build.log 2>&1
cp params/*.param setup/include/picongpu/param/
(cd setup && pic-build -j 16) >> build.log 2>&1 || { tail -n 60 build.log; exit 1; }
echo "# compile end: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> container.txt
remaining=""
for entry in $pending; do
  d=${entry%%:*}; seed=${entry##*:}
  if [ -n "$budget" ] && [ $(( $(date +%s) - job_start )) -ge "$budget" ]; then
    remaining="$remaining $seed"; continue
  fi
  cd "$top/$d"
  rm -rf openPMD ./*.dat
  echo "# run $d seed $seed start: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> "$top/container.txt"
  PIC_SEED=$seed mpiexec -n 1 "$top/setup/bin/picongpu" -d 1 1 -g 128 128 -s 3391 --periodic 1 1 --currentInterpolation none --fieldBackground.duplicateFields --openPMD.period 16 --openPMD.file simData --openPMD.ext h5 --openPMD.infix NULL --openPMD.source fields_all --fields_energy.period 4 --chargeConservation.period 16 --electron_energy.period 4 --electron_energy.filter all > picongpu.log 2>&1 \
    || { tail -n 60 picongpu.log; exit 1; }
  echo "# run $d seed $seed end: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> "$top/container.txt"
done
if [ -n "$remaining" ]; then echo "# seeds remaining after the budget:$remaining"; else echo "# all seeds done"; fi
